'use strict';

/*
═══════════════════════════════════════════════════════════════
   Universal IOSSecurity Bypass (v2 - Hardened)
   Target : iOS Apps using IOSSecurity

   Improvements:
     • Explicit return control (no ambiguity)
     • Strict symbol matching (regex-based)
     • ObjC fallback support (high reliability)
     • Safer + cleaner logging
     • Reduced false positives

   Author : Slayer
═══════════════════════════════════════════════════════════════
*/

const hookedAddresses = new Set();

/* =========================
   CONFIG (EXPLICIT CONTROL)
========================= */

// Set based on target behavior
const FORCE_CLEAN = 1;   // change to 0 if needed after validation
const FORCE_FALSE = 0;

const ENABLE_PREVIEW = false; // set true to log matches without hooking

/* ========================= */

function isExecutable(address) {
    try {
        if (!address || address.isNull()) return false;
        const range = Process.findRangeByAddress(address);
        return !!(range && range.protection && range.protection.includes('x'));
    } catch (_) {
        return false;
    }
}

function safeAttach(addr, name, meta) {
    if (!addr || addr.isNull()) return false;

    const key = addr.toString();
    if (hookedAddresses.has(key)) return false;
    if (!isExecutable(addr)) return false;

    if (ENABLE_PREVIEW) {
        console.log(`[PREVIEW] ${name} @ ${addr}`);
        return false;
    }

    try {
        Interceptor.attach(addr, {
            onLeave: function (retval) {

                if (meta?.hookType === 'performChecks') {
                    retval.replace(FORCE_CLEAN);
                    console.log(`[Slayer] ${name} → forced CLEAN state`);
                }

                else if (meta?.hookType === 'boolAPI') {
                    retval.replace(FORCE_FALSE);
                    console.log(`[Slayer] ${name} → forced Bool = false`);
                }

                else {
                    try { retval.replace(FORCE_FALSE); } catch (_) {}
                    console.log(`[Slayer] ${name} → fallback forced false`);
                }
            }
        });

        hookedAddresses.add(key);
        return true;

    } catch (err) {
        console.log(`[!] Hook failed ${name} @ ${addr}: ${err}`);
        return false;
    }
}

/* =========================
   ObjC HIGH-RELIABILITY HOOK
========================= */

function hookObjC() {
    if (!ObjC.available) return false;

    try {
        const cls = ObjC.classes.JailbreakChecker;
        if (!cls) return false;

        let hooked = false;

        if (cls['- performChecks']) {
            Interceptor.attach(cls['- performChecks'].implementation, {
                onLeave(retval) {
                    retval.replace(FORCE_CLEAN);
                    console.log('[ObjC] performChecks → forced CLEAN');
                }
            });
            hooked = true;
        }

        [
            'amIJailbroken',
            'amIDebugged',
            'amIRuntimeHooked',
            'amIReverseEngineered'
        ].forEach(method => {
            if (cls[`- ${method}`]) {
                Interceptor.attach(cls[`- ${method}`].implementation, {
                    onLeave(retval) {
                        retval.replace(FORCE_FALSE);
                        console.log(`[ObjC] ${method} → false`);
                    }
                });
                hooked = true;
            }
        });

        if (hooked) {
            console.log('[✓] ObjC JailbreakChecker hooks installed');
            return true;
        }

    } catch (e) {
        console.log('[!] ObjC hook error:', e);
    }

    return false;
}

/* =========================
   SYMBOL HOOKING (STRICT)
========================= */

const PERFORM_REGEX = /JailbreakChecker.*performChecks/i;
const BOOL_REGEX = /(amIJailbroken|amIDebugged|amIRuntimeHooked|amIReverseEngineered)/i;

function scanSymbols() {

    let foundPerform = false;
    let foundBool = false;

    Process.enumerateModules().forEach(module => {
        try {
            module.enumerateSymbols().forEach(sym => {

                if (!sym?.name) return;

                if (PERFORM_REGEX.test(sym.name)) {

                    if (safeAttach(sym.address,
                        `${module.name} -> ${sym.name}`,
                        { hookType: 'performChecks' })) {

                        console.log(`[+] performChecks hooked in ${module.name}`);
                        foundPerform = true;
                    }
                }

                else if (BOOL_REGEX.test(sym.name)) {

                    if (safeAttach(sym.address,
                        `${module.name} -> ${sym.name}`,
                        { hookType: 'boolAPI' })) {

                        console.log(`[+] Bool API hooked in ${module.name}`);
                        foundBool = true;
                    }
                }

            });
        } catch (_) {}
    });

    return foundPerform || foundBool;
}

/* =========================
   ENTRY
========================= */

setImmediate(function () {

    console.log('[*] IOSSecurity bypass starting (Hardened v2)');

    const objcHooked = hookObjC();
    const symbolHooked = scanSymbols();

    if (!objcHooked && !symbolHooked) {
        console.log('[!] No hooks applied');
        console.log('[i] Possible reasons:');
        console.log('    • Symbols stripped');
        console.log('    • Static linking');
        console.log('    • Different framework implementation');
    } else {
        console.log('[✓] Hooking completed');
    }

    console.log(`[Slayer] total hooks: ${hookedAddresses.size}`);
});

/*
═══════════════════════════════════════════════════════════════
   no_exit_please_ios.js
   Universal Frida No-Exit Harness (Objective-C + Native)

   Purpose : Block application termination to enable
             reverse engineering and security analysis
   Author  : Slayer
   Version : 1.2
═══════════════════════════════════════════════════════════════
*/

'use strict';

/* =========================
 * Native-level hooks
 * ========================= */

function installNativeHooks() {

    function safeReplace(moduleName, symbol, ret, args, impl) {
        const addr = Module.findExportByName(moduleName, symbol);
        if (!addr) {
            console.log('[i] Native symbol not found:', symbol);
            return;
        }

        Interceptor.replace(addr, new NativeCallback(impl, ret, args));
        console.log('[+] Replaced native', symbol);
    }

    try {

        safeReplace(null, 'exit', 'void', ['int'], function(code) {
            console.log('[BLOCKED][Slayer] exit(' + code + ')');
        });

        safeReplace(null, '_exit', 'void', ['int'], function(code) {
            console.log('[BLOCKED][Slayer] _exit(' + code + ')');
        });

        safeReplace(null, 'abort', 'void', [], function() {
            console.log('[BLOCKED][Slayer] abort()');
        });

        safeReplace(null, 'kill', 'int', ['int', 'int'], function(pid, sig) {
            console.log('[BLOCKED][Slayer] kill(' + pid + ',' + sig + ')');
            return 0;
        });

        safeReplace(null, 'pthread_exit', 'void', ['pointer'], function(retval) {
            console.log('[BLOCKED][Slayer] pthread_exit()');
        });

        safeReplace(null, '__assert_rtn', 'void', ['pointer', 'pointer', 'int', 'pointer'],
            function(func, file, line, expr) {
                console.log('[BLOCKED][Slayer] __assert_rtn()');
            });

    } catch (e) {
        console.log('[-] Native hook error:', e);
    }
}

/* =========================
 * Objective-C hooks
 * ========================= */

