function hookWebSocket() {

    // ── Outgoing (SRWebSocket) ────────────────────────────────────────────
    const SRWebSocket = ObjC.classes.SRWebSocket;
    if (!SRWebSocket) {
        console.log("[WS] SRWebSocket not found.");
