        const sendBin = SRWebSocket["- sendData:error:"];
        if (sendBin) {
            Interceptor.attach(sendBin.implementation, {
                onEnter(args) {
                    try {
                        const data = new ObjC.Object(args[2]);
                        if (data.isKindOfClass_(ObjC.classes.NSData)) {
                            const len = data.length();
                            const bytes = Memory.readByteArray(data.bytes(), len);
