                    } catch (e) {
                        console.log("[WS OUT] error:", e);
                    }
                }
            });
            console.log("[WS] Outgoing (binary) hooked.");
        }

        const sendStr = SRWebSocket["- sendString:error:"];
        if (sendStr) {
            Interceptor.attach(sendStr.implementation, {
                onEnter(args) {
                    try {
                        const msg = new ObjC.Object(args[2]);
                        if (!msg.isNull()) console.log("[WS TEXT OUT]", msg.toString());
                    } catch (e) {}
                }
            });
            console.log("[WS] Outgoing (text) hooked.");
        }
    }

    // ── Incoming (Cheapshot.SocketManager) ───────────────────────────────
    const SocketManager = ObjC.classes["Cheapshot.SocketManager"];
    if (!SocketManager) {
        console.log("[WS] SocketManager not found, retrying in 200ms...");
        setTimeout(function () {
            ObjC.schedule(ObjC.mainQueue, hookWebSocket);
        }, 200);
        return;
    }

    const recvSel = "webSocket:didReceiveMessage:";
    if (SocketManager["- " + recvSel]) {
        Interceptor.attach(SocketManager["- " + recvSel].implementation, {
            onEnter(args) {
                try {
                    const msg = new ObjC.Object(args[3]);
                    if (msg.isKindOfClass_(ObjC.classes.NSData)) {
                        const len = msg.length();
                        const bytes = Memory.readByteArray(msg.bytes(), len);
                        console.log("\n[WS IN] " + len + " bytes");
                        console.log(hexdump(bytes, { ansi: false }));
                    } else {
