                    }
                } catch (e) {
                    console.log("[WS IN] error:", e);
                }
            }
        });
        console.log("[WS] Incoming hooked on Cheapshot.SocketManager.");
    }

    console.log("[WS] WebSocket monitor active (in + out).");
}


