// ════════════════════════════════════════════════════════════════════════════

function hookZoomBypass() {
    const GMSMapView = ObjC.classes.GMSMapView;
    if (!GMSMapView) {
        console.log("[ZOOM] GMSMapView not loaded yet, retrying in 500ms...");
        setTimeout(function () {
            ObjC.schedule(ObjC.mainQueue, hookZoomBypass);
        }, 500);
