            ["pointer", "pointer", "float", "float"]);
        Interceptor.replace(m1.implementation, new NativeCallback(
            function (self, sel, minZoom, maxZoom) {
                console.log("[ZOOM] setMinZoom:maxZoom: " + minZoom.toFixed(2) + " → 0.0");
